input2 = [
    [8, 8, 6],
    [6, 3, 6],
    [6, 8, 8]
]

def flip_h(grid):
    return [row[::-1] for row in grid]

def flip_v(grid):
    return grid[::-1]

def flip_b(grid):
    return [row[::-1] for row in grid[::-1]]

# Versions
